import{_ as e,o as a,c as l,a0 as i}from"./chunks/framework.DqMqoJl9.js";const p="/assets/http_20201103210828.BKUitB2U.png",o="/assets/http_20201103212513.C4FwwMqX.png",r="/assets/http_20201103214257.BRTi9wll.png",s="/assets/http_20201103215036.DZaBs7a9.png",h="/assets/http_20201103215451.UncqFTst.png",n="/assets/http_20201105193140.CzWlTXVx.png",g=JSON.parse('{"title":"传输安全","description":"","frontmatter":{},"headers":[],"relativePath":"loophole/http.md","filePath":"loophole/http.md","lastUpdated":1791573371000}'),c={name:"loophole/http.md"};function _(d,t,u,S,m,T){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="传输安全" tabindex="-1">传输安全 <a class="header-anchor" href="#传输安全" aria-label="Permalink to &quot;传输安全&quot;">​</a></h1><h2 id="_1-http-窃听" tabindex="-1">1 http 窃听 <a class="header-anchor" href="#_1-http-窃听" aria-label="Permalink to &quot;1 http 窃听&quot;">​</a></h2><p>http 协议是明文协议，也就是说请求不会做加密变换，直接发送到网络中，然后传输到服务器。服务器的返回也是明文返回，不做加密，经过各种链路和网络返回的浏览器</p><p><img src="'+p+'" alt=""></p><p>这里的链路就是网络上的各种中转设备，路由器、网关等</p><p>也就是说浏览器跟服务器之间的通信会经过非常多的节点，这些节点每一个都会转发流量数据，转发过程中可以知道这些数据的内容，并且可以修改数据。这就是传输链路的窃听和修改</p><p>使用 <code>traceroute</code> 可以查看一个访问到达服务器需要经过的节点</p><p><img src="'+o+'" alt=""></p><h2 id="_2-危害" tabindex="-1">2 危害 <a class="header-anchor" href="#_2-危害" aria-label="Permalink to &quot;2 危害&quot;">​</a></h2><p>http 窃听：</p><ul><li>窃听用户密码</li><li>窃听传输的敏感信息</li><li>非法获取个人资料</li></ul><p>http 篡改：</p><ul><li>插入广告 (网页中会出现一些广告，但并不是网站的制作者放的，而是在传输过程中放入的)</li><li>重定向网站 (http 响应可以被随意修改)</li><li>无法防御的 XSS 和 CSRF 攻击 (前面提到的防御方式都可以被修改)</li></ul><h2 id="_3-案例" tabindex="-1">3 案例 <a class="header-anchor" href="#_3-案例" aria-label="Permalink to &quot;3 案例&quot;">​</a></h2><h3 id="_3-1-运营商劫持" tabindex="-1">3.1 运营商劫持 <a class="header-anchor" href="#_3-1-运营商劫持" aria-label="Permalink to &quot;3.1 运营商劫持&quot;">​</a></h3><p>访问某个网页时弹出运营商的广告，运营商可以查看和修改你所有传输的数据：</p><p><img src="'+r+'" alt=""> (弹页面形式的广告)</p><p><img src="'+s+'" alt=""> (页面内嵌的小广告)</p><h3 id="_3-2-局域网劫持" tabindex="-1">3.2 局域网劫持 <a class="header-anchor" href="#_3-2-局域网劫持" aria-label="Permalink to &quot;3.2 局域网劫持&quot;">​</a></h3><p>通过一些手段将局域网中的流量导入到自己的机器，相当于自己的机器成了一个代理</p><p><img src="'+h+'" alt=""></p><p>比如当访问支付宝网页(已修复)的时候，你访问到的网页经过攻击者的机器后，已经被插入了一些恶意代码，这样就能盗取到用户名和密码</p><h3 id="_3-3-公共-wifi" tabindex="-1">3.3 公共 wifi <a class="header-anchor" href="#_3-3-公共-wifi" aria-label="Permalink to &quot;3.3 公共 wifi&quot;">​</a></h3><p>连了一个 wifi 后，你所有的流量都会经过那个路由器。这些数据都可能被查看和修改</p><h2 id="_4-https" tabindex="-1">4 https <a class="header-anchor" href="#_4-https" aria-label="Permalink to &quot;4 https&quot;">​</a></h2><p>HTTPS（全称：Hyper Text Transfer Protocol over Secure Socket Layer），是以安全为目标的 HTTP 通道，简单讲是 HTTP 的安全版。即 HTTP 下加入 SSL 层，HTTPS 的安全基础是 SSL，因此加密的详细内容就需要 SSL</p><p>http 协议的缺点：</p><ul><li><strong>通信使用明文</strong> 通信使用明文意味着安全性大大降低，当通信过程被窃听后，无需花费额外的投入就可看到传输的数据。例如使用抓包工具，无需任何配置就可查看任何使用 HTTP 协议的通信数据</li><li><strong>不验证通信方身份</strong> 不验证通信方的身份，将导致通信过程被窃听后，可能会遭遇伪装，例如使用抓包工具抓取数据后，就可按照数据包的格式构造 HTTP 请求</li><li><strong>无法验证报文的完整性</strong> 不验证报文的完整性，数据在传输过程中就可能被篡改</li></ul><p><code>Https = Http + 加密 + 认证 + 完整性验证</code></p><blockquote><p>如果直接使用对称加密的方式进行加密，如果密钥不被泄漏是安全，但问题是密钥无法传递给客户端。而非对称加密，数据传输之前，服务端将自己的公钥传输给客户端，客户端在传输数据时，使用接收的公钥进行加密，服务端接收到数据后使用私钥进行解密，理论上可行，但是解密计算量很大，效率低。所以 https 使用到 TLS(SSL) 协议加密</p></blockquote><p>TLS 协议的握手过程:</p><ol><li>客户端先给服务端发送一个消息，消息内容包括：客户端支持的加密方式，支持的压缩方法，SSL 的版本号，客户端生成的随机数，文本内容“Hello”等</li><li>服务端接收到消息后，也回发一个 Hello，并携带从客户端支持的加密方式中选择的加密方式，服务端生成的随机数，服务端的 SSL 版本号等信息</li><li>随后服务器给客户端发送一个 Certificate 报文，报文中包含服务端的公钥证书</li><li>紧接着服务器给客户端发送 Server Hello Done, 表示最初的协商握手过程结束</li><li>客户端接收到服务端发送的握手结束的消息后，以 Client Key Exchange 作为回应，此报文中包含通信加密过程中使用的一种被称为 Pre-master secret 的随机密码串，并使用第三步接收到的公钥证书进行了加密</li><li>接着客户端发送 Change Cipher Spec 报文，该报文告知服务端，此步骤之后的所有数据将使用第五步中生成的 master secret 进行加密</li><li>随后客户端发送 Finish 报文，此报文中包含连接至今所有报文的整体校验值，用于完整性验证</li><li>服务端接收到客户端发送的 Change Cliper Spec 报文后，同样以 Change Cliper Spec 报文作为回应</li><li>接着服务端发送 Finish 报文给客户端，表示服务端已正确解析客户端发送的整体校验值，至此，SSL 握手的过程结束</li><li>随后开始使用 HTTP 协议传输使用 master secret 加密过的数据</li></ol><p><img src="'+n+'" alt=""></p><blockquote><p>证书需要向正规的服务商申请，而且浏览器内置了一个信任的 CA 证书列表，如果证书不是来自这个列表那么校验不通过</p></blockquote><p>TLS 协议安全性几个关键的点：</p><ul><li>证书无法伪造 (证书是向 CA 申请的)</li><li>证书私钥不被泄漏 (保证服务端不被攻击，私钥被盗)</li><li>域名管理权不泄漏</li><li>CA 坚守原则 (CA 不随意发证书)</li></ul>',36)])])}const q=e(c,[["render",_]]);export{g as __pageData,q as default};
